      this.http.post<BulkSettled>(`${this.url(sheet)}/claims/bulk-settle`, { claimIds }, {
        headers: this.session.headers(),
      }),
    );
  }

  /** Move each of the claims that can be moved to the person, in list order, by the rules of moving
